def partition(key, num_reduce):
    h = 0
    for ch in key:
        h = (h * 31 + ord(ch)) & 0x7fffffff
    return h % num_reduce

R = 3
words = ["hello", "world", "bigdata", "of", "data", "map", "reduce", "spark"]
for w in words:
    print(f"{w:10s} -> ‹1› {partition(w, R)}")
print(f"--num_reducers={R}")
